contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        c.XBornID();
        address alice = address(0x1111);
        address bob = address(0x2222);

        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getTokens();
        uint256 totalAfterAlice = c.totalDistributed();

        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.getTokens();
        uint256 totalAfterBob = c.totalDistributed();

        vm.deal(alice, 1 ether);
        vm.prank(alice);

        bool aliceSecondSucceeded;
        try c.getTokens() { aliceSecondSucceeded = true; } catch { aliceSecondSucceeded = false; }

        assertTrue(aliceSecondSucceeded == false);
    }
}
